display.text:
/* ==========================================================================
   ARYORITHM TECHNOLOGIES — SHARED APPLICATION SHELL
   Design tokens, animation hooks, hash router, global header and footer.
   Every page script is IIFE-scoped and publishes itself onto window.ARY so
   the separate Babel <script> tags never collide in global lexical scope.
   ========================================================================== */

window.ARY = window.ARY || {};

(function () {
  'use strict';

  const { useState, useEffect, useRef, useCallback } = React;

  /* -------------------------------------------------------------- tokens -- */
  const TOKEN = {
    void: '#07090E',
    panel: '#0D111A',
    hairline: '#1A2232',
    cyan: '#00E5FF',
    kernel: '#00FFA3',
    threat: '#FF3366',
    telemetry: '#FFB800',
    ink: '#F0F4F8',
    muted: '#8A99AD'
  };

  /* ----------------------------------------------------------- utilities -- */
  function useInView(options) {
    const ref = useRef(null);
    const [inView, setInView] = useState(false);
    useEffect(() => {
      const node = ref.current;
      if (!node) return;
      if (typeof IntersectionObserver === 'undefined') { setInView(true); return; }
      const obs = new IntersectionObserver((entries) => {
        entries.forEach((e) => { if (e.isIntersecting) { setInView(true); obs.disconnect(); } });
      }, Object.assign({ threshold: 0.25 }, options || {}));
      obs.observe(node);
      return () => obs.disconnect();
    }, []);
    return [ref, inView];
  }

  /** Eased count-up for telemetry metric values. */
  function useCountUp(target, active, duration) {
    const [value, setValue] = useState(0);
    useEffect(() => {
      if (!active) return;
      const total = duration || 1600;
      let raf = 0;
      const start = performance.now();
      const tick = (now) => {
        const t = Math.min(1, (now - start) / total);
        const eased = 1 - Math.pow(1 - t, 3);
        setValue(target * eased);
        if (t < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
      return () => cancelAnimationFrame(raf);
    }, [target, active, duration]);
    return value;
  }

  const fmtInt = (n) => Math.round(n).toLocaleString('en-US');

  /**
   * Copy text to the clipboard.
   * The async Clipboard API REJECTS (rather than being absent) when the
   * document lacks permission — headless browsers, non-secure origins and
   * some embedded webviews all do this. So we must catch the rejection and
   * fall back to the legacy selection path, not merely feature-detect.
   * Returns true when some mechanism reported success.
   */
  function legacyCopy(text) {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.top = '0';
      ta.style.left = '0';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      ta.setSelectionRange(0, text.length);
      const ok = document.execCommand('copy');
      document.body.removeChild(ta);
      return ok;
    } catch (err) {
      return false;
    }
  }

  async function copyText(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch (err) {
        // Permission denied or insecure context — fall through.
      }
    }
    return legacyCopy(text);
  }

  /* -------------------------------------------------------------- router -- */
  /* Hash route grammar:  #<path>[@<section-id>]
     e.g. #/platform/nexus@nexus-capabilities                               */
  const ROUTES = {
    '/': 'Global Homepage',
    '/platform/nexus': 'Sentinel Nexus — Tier 6 Command Plane',
    '/products/sentinel': 'Blackbox Sentinel — Tier 3 Edge Appliance',
    '/technology/xinfer': 'xInfer Engine — Tier 1 Silicon Runtime',
    '/technology/blackbox': 'Blackbox Core — Tier 2 Kernel Engine',
    '/technology/forge': 'xInfer Forge — Tier 4 Continuous Learning',
    '/pricing': 'Enterprise Pricing & Licensing',
    '/trust': 'Sovereign Trust, Verification & Compliance',
    '/about': 'Company Mission & Sovereignty',
    '/contact': 'Defense Procurement & Encrypted Inquiries',
    '/research/sentinel-lab': 'Sentinel-Lab — Open Research & Benchmark Platform',
    '/team': 'Leadership, Architects & Careers',
    '/portal': 'Customer Enclave — Authentication & Activation',
    '/insights': 'Technical Insights & Threat Advisories',
    '/faq': 'Deep-Tech Architectural Q&A'
  };

  function parseHash() {
    const raw = (window.location.hash || '').replace(/^#/, '');
    if (!raw) return { path: '/', section: null };
    const at = raw.indexOf('@');
    let path = at === -1 ? raw : raw.slice(0, at);
    const section = at === -1 ? null : raw.slice(at + 1);
    if (!path.startsWith('/')) path = '/' + path;
    if (path.length > 1) path = path.replace(/\/+$/, '');
    if (!Object.prototype.hasOwnProperty.call(ROUTES, path)) return { path: '/', section: null };
    return { path: path, section: section || null };
  }

  function hrefFor(to, section) {
    return '#' + to + (section ? '@' + section : '');
  }

  function scrollToSection(section) {
    if (!section) { window.scrollTo({ top: 0, behavior: 'auto' }); return; }
    requestAnimationFrame(() => {
      const el = document.getElementById(section);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      else window.scrollTo({ top: 0, behavior: 'auto' });
    });
  }

  /** Route state + smooth section handoff between pages. */
  function useRouter() {
    const [route, setRoute] = useState(parseHash);
    useEffect(() => {
      const onHash = () => setRoute(parseHash());
      window.addEventListener('hashchange', onHash);
      return () => window.removeEventListener('hashchange', onHash);
    }, []);

    // Re-run the scroll handoff whenever either path or section changes.
    useEffect(() => {
      scrollToSection(route.section);
      const label = ROUTES[route.path] || ROUTES['/'];
      document.title = 'Aryorithm Technologies — ' + label;
    }, [route.path, route.section]);

    return route;
  }

  /**
   * Router-aware anchor. Renders a real href so links are copyable and
   * keyboard/middle-click friendly, and forces the scroll handoff when the
   * target hash is identical to the current one (no hashchange would fire).
   */
  function Link(props) {
    const { to, section, className, children, onDone } = props;
    const href = hrefFor(to, section);
    const handle = (e) => {
      if (onDone) onDone();
      const current = window.location.hash || '#/';
      if (current === href) {
        e.preventDefault();
        scrollToSection(section);
      }
    };
    return (
      <a href={href} className={className} onClick={handle} aria-label={props['aria-label']}>
        {children}
      </a>
    );
  }

  /* ---------------------------------------------------- shared UI pieces -- */
  function Kicker(props) {
    return (
      <span className="font-mono text-[10px] uppercase tracking-[0.24em] text-cyan">
        {'// ' + props.children}
      </span>
    );
  }

  /** Monospace pill badge, e.g. [ TIER 6 COMMAND PLANE ] */
  function PillBadge(props) {
    const color = props.color || TOKEN.cyan;
    return (
      <span className="inline-block rounded-md border border-hairline bg-panel/80 px-2.5 py-1.5 font-mono text-[10px] uppercase tracking-[0.13em] text-muted">
        <span style={{ color: color }}>[</span> {props.children} <span style={{ color: color }}>]</span>
      </span>
    );
  }

  function StatStrip(props) {
    const items = props.items || [];
    return (
      <dl className={'grid divide-x divide-hairline border-hairline ' + (props.className || '')}
        style={{ gridTemplateColumns: 'repeat(' + items.length + ', minmax(0, 1fr))' }}>
        {items.map((it) => (
          <div key={it[0]} className="px-3 py-3">
            <dt className="font-mono text-[8.5px] uppercase tracking-[0.14em] text-muted">{it[0]}</dt>
            <dd className="mt-1 font-mono text-[12px] tabular" style={{ color: it[2] || TOKEN.ink }}>{it[1]}</dd>
          </div>
        ))}
      </dl>
    );
  }

  /* ------------------------------------------------------- breadcrumb ----- */
  function Breadcrumb(props) {
    const trail = props.trail || [];
    return (
      <nav aria-label="Breadcrumb" className="mb-5 flex flex-wrap items-center font-mono text-[10px] uppercase tracking-[0.16em] text-muted">
        <Link to="/" className="transition-colors hover:text-cyan">Home</Link>
        {trail.map((step, i) => (
          <React.Fragment key={step.label}>
            <span className="mx-2 text-hairline" aria-hidden="true">/</span>
            {step.to ? (
              <Link to={step.to} section={step.section} className="transition-colors hover:text-cyan">{step.label}</Link>
            ) : (
              <span className={i === trail.length - 1 ? 'text-cyan' : 'text-muted'}>{step.label}</span>
            )}
          </React.Fragment>
        ))}
      </nav>
    );
  }

  /* -------------------------------------------------------- code viewer -- */
  /* Lightweight tokeniser. Deliberately regex-based and dependency-free —
     the appliance UI ships no highlighter library.                          */
  const SYNTAX = {
    cpp: {
      comment: /\/\/[^\n]*/,
      string: /"(?:[^"\\]|\\.)*"|<[A-Za-z0-9_./]+>(?=\s*$)/,
      preproc: /^\s*#\s*[a-z]+/,
      keyword: /\b(?:auto|const|constexpr|namespace|using|return|if|else|for|while|struct|class|public|private|void|int|size_t|uint8_t|uint16_t|uint32_t|uint64_t|float|double|bool|true|false|nullptr|static|inline|noexcept|template|typename|co_await|span|expected)\b/,
      number: /\b\d+(?:\.\d+)?(?:[uUlLfF]|us|ms|ns)?\b/,
      type: /\b(?:xinfer|blackbox|Engine|Tensor|DmaBuffer|InferenceRequest|Backend|Status|std|chrono|vector|string_view|array)\b/,
      punct: /[{}()[\];,<>:&*=+\-/.!|]/
    },
    yaml: {
      comment: /#[^\n]*/,
      key: /^\s*-?\s*[A-Za-z0-9_.-]+(?=\s*:)/,
      string: /"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'/,
      number: /\b\d+(?:\.\d+)?\b/,
      keyword: /\b(?:true|false|null|required|abort|pass)\b/,
      punct: /[:\-[\]{},]/
    }
  };

  const SYNTAX_COLORS = {
    comment: '#5A6B82',
    string: '#00FFA3',
    preproc: '#FFB800',
    keyword: '#00E5FF',
    number: '#FFB800',
    type: '#F0F4F8',
    key: '#00E5FF',
    punct: '#8A99AD',
    plain: '#C3CEDB'
  };

  function highlightLine(line, lang) {
    const rules = SYNTAX[lang];
    if (!rules) return [{ text: line, kind: 'plain' }];
    const order = Object.keys(rules);
    const out = [];
    let rest = line;
    let guard = 0;

    while (rest.length && guard++ < 400) {
      let best = null;
      for (let i = 0; i < order.length; i++) {
        const kind = order[i];
        const m = rules[kind].exec(rest);
        if (m && m[0].length && (best === null || m.index < best.index)) {
          best = { index: m.index, text: m[0], kind: kind };
          if (m.index === 0) break;
        }
      }
      if (!best) { out.push({ text: rest, kind: 'plain' }); break; }
      if (best.index > 0) out.push({ text: rest.slice(0, best.index), kind: 'plain' });
      out.push({ text: best.text, kind: best.kind });
      rest = rest.slice(best.index + best.text.length);
    }
    return out;
  }

  function CodeViewer(props) {
    const { code, lang, filename, note } = props;
    const [copied, setCopied] = useState(false);
    const lines = code.replace(/\s+$/, '').split('\n');

    const copy = async () => {
      await copyText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    };

    return (
      <figure className="m-0 overflow-hidden rounded-md border border-hairline bg-panel">
        <figcaption className="flex items-center gap-3 border-b border-hairline bg-void/70 px-4 py-2.5">
          <span className="flex gap-1.5" aria-hidden="true">
            <span className="h-2.5 w-2.5 rounded-full bg-threat/70"></span>
            <span className="h-2.5 w-2.5 rounded-full bg-telemetry/70"></span>
            <span className="h-2.5 w-2.5 rounded-full bg-kernel/70"></span>
          </span>
          <span className="min-w-0 flex-1 truncate font-mono text-[10.5px] text-muted">{filename}</span>
          <button type="button" onClick={copy}
            className={'shrink-0 rounded-md border px-2.5 py-1 font-mono text-[9.5px] uppercase tracking-[0.12em] transition-colors ' +
              (copied ? 'border-kernel/60 text-kernel' : 'border-hairline text-muted hover:border-cyan/60 hover:text-cyan')}>
            {copied ? '✓ Copied' : 'Copy Snippet'}
          </button>
        </figcaption>

        <div className="terminal-scroll overflow-x-auto bg-void">
          <pre className="m-0 px-0 py-3 font-mono text-[11.5px] leading-[1.75] sm:text-[12px]"><code>
            {lines.map((line, li) => (
              <div key={li} className="flex px-4 hover:bg-cyan/[0.03]">
                <span className="mr-4 w-[22px] shrink-0 select-none text-right text-muted/45 tabular" aria-hidden="true">{li + 1}</span>
                <span className="whitespace-pre">
                  {highlightLine(line, lang).map((tok, ti) => (
                    <span key={ti} style={{ color: SYNTAX_COLORS[tok.kind] || SYNTAX_COLORS.plain }}>{tok.text}</span>
                  ))}
                </span>
              </div>
            ))}
          </code></pre>
        </div>

        {note && (
          <div className="border-t border-hairline bg-void/60 px-4 py-2.5 font-mono text-[10px] text-muted">{note}</div>
        )}
      </figure>
    );
  }

  /* ----------------------------------------------- navigation definition -- */
  const NAV = [
    {
      label: 'Platform',
      match: ['/platform/nexus'],
      items: [
        { name: 'Sentinel Nexus', desc: 'Tier 6 collective defense command plane', to: '/platform/nexus' },
        { name: 'Nexus Command Center', desc: 'Port 9443 fleet HUD simulation', to: '/platform/nexus', section: 'nexus-command-center' },
        { name: 'Fleet Overview', desc: 'Health, canary waves, heartbeat meters', to: '/platform/nexus', section: 'nexus-command-center' },
        { name: 'OTA Canary Pipeline', desc: 'Shadow → 5% cohort → fleet promote', to: '/platform/nexus', section: 'nexus-capabilities' }
      ]
    },
    {
      label: 'Products',
      match: ['/products/sentinel'],
      items: [
        { name: 'Blackbox Sentinel Edge', desc: 'Tier 3 cyber-physical XDR appliance', to: '/products/sentinel' },
        { name: 'Appliance Form Factors', desc: 'S-1000 · S-5000 · V-Edge', to: '/products/sentinel', section: 'form-factors' },
        { name: '26 Subsystems', desc: 'Decoupled native module matrix', to: '/products/sentinel', section: 'subsystem-matrix' },
        { name: '30 Industrial Plugins', desc: 'dlopen protocol dissector catalogue', to: '/products/sentinel', section: 'plugin-showcase' }
      ]
    },
    {
      label: 'Technology',
      match: ['/technology/xinfer', '/technology/blackbox', '/technology/forge'],
      items: [
        { name: 'xInfer Engine', desc: 'libxinfer.so — 15 silicon backends', to: '/technology/xinfer' },
        { name: 'Silicon Matrix', desc: '15-platform zero-copy support grid', to: '/technology/xinfer', section: 'silicon-matrix' },
        { name: 'Blackbox Core', desc: 'libblackbox.so — eBPF/XDP kernel engine', to: '/technology/blackbox' },
        { name: 'Fast-Path Inspection', desc: 'Frame lifecycle to XDP_DROP', to: '/technology/blackbox', section: 'fast-path' },
        { name: 'xInfer Forge', desc: 'Air-gapped continual learning service', to: '/technology/forge' },
        { name: 'Regression Safety Gate', desc: 'golden_attacks.yaml watchdog', to: '/technology/forge', section: 'safety-gate' }
      ]
    },
    {
      label: 'Research',
      match: ['/research/sentinel-lab', '/insights', '/faq'],
      items: [
        { name: 'Sentinel-Lab', desc: 'Tier 5 open research & benchmark platform', to: '/research/sentinel-lab' },
        { name: 'Academic Preprint', desc: 'Sub-millisecond active defense (PDF)', to: '/research/sentinel-lab', section: 'preprint' },
        { name: 'SLAB Wire Protocol', desc: 'Zero-allocation binary frame spec', to: '/research/sentinel-lab', section: 'slab-protocol' },
        { name: 'Technical Insights', desc: 'Kernel dissections & post-mortems', to: '/insights' },
        { name: 'Architectural FAQ', desc: 'Deep-tech engineering answers', to: '/faq' },
        { name: 'Open Research Tier', desc: 'Free open-core libraries & benchmarks', to: '/pricing', section: 'licensing-matrix' }
      ]
    },
    {
      label: 'Company',
      match: ['/about', '/trust', '/contact', '/team'],
      items: [
        { name: 'Mission & Sovereignty', desc: 'The Aryorithm manifesto & four pillars', to: '/about' },
        { name: 'Team & Careers', desc: 'Systems & kernel architects · open roles', to: '/team' },
        { name: 'Sovereign Trust', desc: 'Attestation, crosswalks & SBOM repository', to: '/trust' },
        { name: 'Standards & Compliance', desc: 'CMMC 2.0 · IEC 62443 · NIS2', to: '/trust', section: 'regulatory-crosswalks' },
        { name: 'Defense Procurement', desc: 'Encrypted intake & clearance desk', to: '/contact' }
      ]
    },
    { label: 'Pricing', match: ['/pricing'], to: '/pricing' }
  ];

  /* -------------------------------------------------------------- header -- */
  function Header(props) {
    const activePath = props.activePath || '/';
    const [open, setOpen] = useState(null);
    const [mobileOpen, setMobileOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
      const onScroll = () => setScrolled(window.scrollY > 12);
      onScroll();
      window.addEventListener('scroll', onScroll, { passive: true });
      return () => window.removeEventListener('scroll', onScroll);
    }, []);

    // Collapse the mobile drawer whenever the route changes.
    useEffect(() => { setMobileOpen(false); }, [activePath]);

    return (
      <header
        id="site-header"
        className={
          'fixed top-0 inset-x-0 z-50 border-b transition-colors duration-300 ' +
          (scrolled ? 'border-hairline bg-void/92 backdrop-blur-xl' : 'border-transparent bg-void/70 backdrop-blur-md')
        }
      >
        <div className="mx-auto flex h-16 max-w-[1400px] items-center gap-6 px-5 lg:px-8">
          <Link to="/" className="flex shrink-0 items-center gap-2.5" aria-label="Aryorithm Technologies home">
            <span className="block h-2.5 w-2.5 bg-cyan pip-pulse" style={{ boxShadow: '0 0 12px rgba(0,229,255,0.9)' }} aria-hidden="true"></span>
            <span className="font-display text-[17px] font-bold tracking-[0.16em] text-ink">ARYORITHM</span>
          </Link>

          <nav id="primary-nav" className="hidden flex-1 items-center justify-center lg:flex" aria-label="Primary">
            <ul className="flex items-center gap-1">
              {NAV.map((group) => {
                const isActiveRoute = group.match && group.match.indexOf(activePath) !== -1;
                const isOpen = open === group.label;
                return (
                  <li
                    key={group.label}
                    className="relative"
                    onMouseEnter={() => setOpen(group.items ? group.label : null)}
                    onMouseLeave={() => setOpen(null)}
                  >
                    <Link
                      to={group.items ? group.items[0].to : group.to}
                      section={group.items ? group.items[0].section : group.section}
                      className={
                        'flex items-center gap-1.5 px-3.5 py-2 text-[13.5px] font-medium transition-colors ' +
                        (isOpen || isActiveRoute ? 'text-cyan' : 'text-muted hover:text-ink')
                      }
                    >
                      {group.label}
                      {isActiveRoute && <span className="h-1 w-1 bg-cyan" aria-hidden="true"></span>}
                      {group.items && (
                        <svg width="9" height="9" viewBox="0 0 10 6" fill="none" aria-hidden="true"
                          className={'transition-transform duration-200 ' + (isOpen ? 'rotate-180' : '')}>
                          <path d="M1 1l4 4 4-4" stroke="currentColor" strokeWidth="1.4" />
                        </svg>
                      )}
                    </Link>

                    {group.items && isOpen && (
                      <div className="absolute left-1/2 top-full w-[334px] -translate-x-1/2 pt-2">
                        <div className="rise-in overflow-hidden rounded-md border border-hairline bg-panel shadow-2xl shadow-black/60">
                          <div className="border-b border-hairline px-4 py-2 font-mono text-[10px] uppercase tracking-[0.22em] text-muted">
                            {group.label}
                          </div>
                          <ul className="divide-y divide-hairline/70">
                            {group.items.map((item) => (
                              <li key={item.name}>
                                <Link to={item.to} section={item.section} onDone={() => setOpen(null)}
                                  className="group flex items-start gap-3 px-4 py-3 transition-colors hover:bg-cyan/[0.055]">
                                  <span className="mt-1.5 h-1.5 w-1.5 shrink-0 bg-hairline transition-colors group-hover:bg-cyan" aria-hidden="true"></span>
                                  <span>
                                    <span className="block text-[13.5px] font-medium text-ink transition-colors group-hover:text-cyan">{item.name}</span>
                                    <span className="mt-0.5 block text-[11.5px] leading-snug text-muted">{item.desc}</span>
                                  </span>
                                </Link>
                              </li>
                            ))}
                          </ul>
                        </div>
                      </div>
                    )}
                  </li>
                );
              })}
            </ul>
          </nav>

          <div className="ml-auto hidden items-center gap-3 lg:flex">
            <Link to="/portal" className="rounded-md border border-hairline px-4 py-2 font-mono text-[11.5px] uppercase tracking-[0.1em] text-muted transition-all duration-200 hover:border-cyan/60 hover:text-cyan hover:glow-cyan">
              Customer Enclave Login
            </Link>
            <Link to="/contact" className="rounded-md bg-cyan px-4 py-2 font-mono text-[11.5px] font-bold uppercase tracking-[0.1em] text-void transition-all duration-200 hover:glow-cyan-strong hover:brightness-110">
              Request Defense POC
            </Link>
          </div>

          <button
            type="button"
            id="mobile-nav-toggle"
            onClick={() => setMobileOpen((v) => !v)}
            aria-expanded={mobileOpen}
            aria-controls="mobile-nav"
            aria-label="Toggle navigation"
            className="ml-auto flex h-10 w-10 items-center justify-center rounded-md border border-hairline text-muted transition-colors hover:text-cyan lg:hidden"
          >
            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
              {mobileOpen
                ? <path d="M3 3l12 12M15 3L3 15" stroke="currentColor" strokeWidth="1.5" />
                : <path d="M2 5h14M2 9h14M2 13h14" stroke="currentColor" strokeWidth="1.5" />}
            </svg>
          </button>
        </div>

        {mobileOpen && (
          <nav id="mobile-nav" aria-label="Mobile" className="max-h-[calc(100vh-4rem)] overflow-y-auto border-t border-hairline bg-panel lg:hidden">
            <ul className="divide-y divide-hairline">
              {NAV.map((group) => (
                <li key={group.label} className="px-5 py-3.5">
                  <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-muted">{group.label}</span>
                  {group.items ? (
                    <ul className="mt-2 space-y-2">
                      {group.items.map((item) => (
                        <li key={item.name}>
                          <Link to={item.to} section={item.section} onDone={() => setMobileOpen(false)}
                            className="block text-[14px] text-ink hover:text-cyan">
                            {item.name}
                          </Link>
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <Link to={group.to} section={group.section} onDone={() => setMobileOpen(false)}
                      className="mt-2 block text-[14px] text-ink hover:text-cyan">
                      View {group.label}
                    </Link>
                  )}
                </li>
              ))}
            </ul>
            <div className="space-y-2.5 px-5 py-4">
              <Link to="/portal" onDone={() => setMobileOpen(false)}
                className="block rounded-md border border-hairline px-4 py-2.5 text-center font-mono text-[11.5px] uppercase tracking-[0.1em] text-muted">
                Customer Enclave Login
              </Link>
              <Link to="/contact" onDone={() => setMobileOpen(false)}
                className="block rounded-md bg-cyan px-4 py-2.5 text-center font-mono text-[11.5px] font-bold uppercase tracking-[0.1em] text-void">
                Request Defense POC
              </Link>
            </div>
          </nav>
        )}
      </header>
    );
  }

  /* ------------------------------------------------- closing conversion -- */
  function ClosingCTA() {
    return (
      <section id="poc-cta" className="relative overflow-hidden border-b border-hairline py-16 lg:py-20">
        <div className="pointer-events-none absolute inset-0 grid-backdrop opacity-40" aria-hidden="true"></div>
        <div className="relative mx-auto max-w-[1400px] px-5 lg:px-8">
          <div className="flex flex-col gap-8 rounded-md border border-hairline bg-panel p-7 lg:flex-row lg:items-center lg:justify-between lg:p-10">
            <div className="max-w-2xl">
              <h2 className="font-display text-[24px] font-bold leading-tight tracking-[-0.015em] text-ink lg:text-[30px]">
                Deploy A Two-Node Defense POC In Your Own Air-Gapped Segment.
