            </div>
            <div className="flex shrink-0 flex-col gap-3 sm:flex-row lg:flex-col">
              <Link to="/contact"
                className="rounded-md bg-cyan px-6 py-3.5 text-center font-mono text-[12px] font-bold uppercase tracking-[0.1em] text-void transition-all duration-200 hover:glow-cyan-strong hover:brightness-110">
                [ Request Defense POC ]
