        { label: 'Data Sovereignty Statement', to: '/about', section: 'four-pillars' },
        { label: 'Responsible Disclosure (PGP)', to: '/contact', section: 'pgp-panel' },
        { label: 'Software Bill of Materials', to: '/trust', section: 'sbom-repository' },
        { label: 'Customer Enclave Portal', to: '/portal' },
        { label: 'Offline License Activation', to: '/portal', section: 'portal-container' }
