    Footer: Footer,
    ClosingCTA: ClosingCTA
  });
})();

/* ==========================================================================
   ARYORITHM TECHNOLOGIES — CLIENT-SIDE ROUTER & APP MOUNT
   Loaded last: every page module has registered itself on window.ARY by now.
   ========================================================================== */

(function () {
  'use strict';

  const { useRouter, Header, Footer, ClosingCTA } = window.ARY;

  const PAGES = {
    '/': function () { return <window.ARY.HomePage />; },
    '/platform/nexus': function () { return <window.ARY.NexusPage />; },
    '/products/sentinel': function () { return <window.ARY.SentinelPage />; },
    '/technology/xinfer': function () { return <window.ARY.XInferPage />; },
    '/technology/blackbox': function () { return <window.ARY.BlackboxPage />; },
    '/technology/forge': function () { return <window.ARY.ForgePage />; },
    '/pricing': function () { return <window.ARY.PricingPage />; },
    '/trust': function () { return <window.ARY.TrustPage />; },
    '/about': function () { return <window.ARY.AboutPage />; },
    '/contact': function () { return <window.ARY.ContactPage />; },
    '/research/sentinel-lab': function () { return <window.ARY.LabPage />; },
    '/team': function () { return <window.ARY.TeamPage />; },
    '/portal': function () { return <window.ARY.PortalPage />; },
    '/insights': function () { return <window.ARY.InsightsPage />; },
    '/faq': function () { return <window.ARY.FaqPage />; }
  };

  /* The closing POC panel routes to /contact, so showing it on /contact
     itself would be a link back to the page you are already reading. */
  /* /portal is an authentication surface — a marketing POC panel below a
     login form is noise, and /team closes with its own careers CTA. */
  const SUPPRESS_CTA = ['/contact', '/portal'];

  function App() {
    const route = useRouter();
    const render = PAGES[route.path] || PAGES['/'];
    const showCta = SUPPRESS_CTA.indexOf(route.path) === -1;

    return (
      <React.Fragment>
        <Header activePath={route.path} />
        {/* key forces a clean remount per route so page-local simulations reset */}
        <main id="main-content" key={route.path}>
          {render()}
          {showCta && <ClosingCTA />}
        </main>
        <Footer />
      </React.Fragment>
    );
  }

  ReactDOM.createRoot(document.getElementById('app-root')).render(<App />);
})();

