@tailwind base;
@tailwind components;
@tailwind utilities;

/* ============================================================
   Aryorithm Technologies — Corporate Design System
   Obsidian Void surfaces, hairline structure, monospace telemetry.
   ============================================================ */

:root {
  --void: #07090e;
  --panel: #0d111a;
  --hairline: #1a2232;
  --accent: #00e5ff;
  --kernel: #00ffa3;
  --threat: #ff3366;
  --telemetry: #ffb800;
  --ink: #f0f4f8;
  --muted: #8a99ad;
}

html,
body {
  background-color: var(--void);
}

body {
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* --- Accessibility ---------------------------------------- */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 100;
  background: var(--accent);
  color: var(--void);
  padding: 0.6rem 1rem;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 0.75rem;
}
.skip-link:focus {
  left: 0;
}

:focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 2px;
}

/* --- Scrollbar -------------------------------------------- */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
