/**
 * Universal clipboard copy with resilient fallback.
 * The async Clipboard API REJECTS (rather than being absent) in headless
 * browsers, non-secure origins and sandboxed webviews — so we catch the
 * rejection and fall back to the legacy selection path.
 * Returns true when some mechanism reported success.
 */
function legacyCopy(text: string): boolean {
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.top = "0";
    ta.style.left = "0";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    ta.setSelectionRange(0, text.length);
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

export async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        // Permission denied / insecure context — fall through.
      }
    }
  } catch {
    // navigator itself unavailable — fall through.
  }
  return legacyCopy(text);
}

export function formatCurrency(n: number, decimals = 0): string {
  return n.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

export function formatInt(n: number): string {
  return Math.round(n).toLocaleString("en-US");
}

export function formatMicroseconds(us: number, decimals = 2): string {
  return `${us.toFixed(decimals)} µs`;
}

/** 10 GB -> "10 GB/day", 2000 GB -> "2.0 TB/day" */
export function formatVolumeLabel(gbPerDay: number): string {
  if (gbPerDay >= 1000) {
    const tb = gbPerDay / 1000;
    return `${tb.toFixed(gbPerDay % 1000 === 0 ? 0 : 1)} TB/day`;
  }
  return `${Math.round(gbPerDay)} GB/day`;
}

export function formatBytes(n: number): string {
  if (n >= 1e12) return `${(n / 1e12).toFixed(1)} TB`;
  if (n >= 1e9) return `${(n / 1e9).toFixed(1)} GB`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)} MB`;
  return `${Math.round(n)} B`;
}

