"use client";

import { useEffect, useRef, useState } from "react";
import { ARY_STAGES, CLOUD_STAGES } from "@/data/home";

export default function LatencyComparator() {
  const [running, setRunning] = useState(false);
  const [done, setDone] = useState(false);
  const [cloudTime, setCloudTime] = useState(0);
  const [aryUs, setAryUs] = useState(0);
  const rafRef = useRef(0);

  const simulate = () => {
    cancelAnimationFrame(rafRef.current);
    setRunning(true);
    setDone(false);
    setCloudTime(0);
    setAryUs(0);
    const start = performance.now();
    const ARY_MS = 460;
    const CLOUD_MS = 8400;
    const tick = (now: number) => {
      const el = now - start;
      setAryUs(Math.min(0.84, (Math.min(el, ARY_MS) / ARY_MS) * 0.84));
      setCloudTime(Math.min(41.6, (Math.min(el, CLOUD_MS) / CLOUD_MS) * 41.6));
      if (el < CLOUD_MS) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        setRunning(false);
        setDone(true);
      }
    };
    rafRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => () => cancelAnimationFrame(rafRef.current), []);

  const reset = () => {
    cancelAnimationFrame(rafRef.current);
    setRunning(false);
    setDone(false);
    setCloudTime(0);
    setAryUs(0);
  };

  const aryComplete = aryUs >= 0.84;

  return (
    <div id="latency-comparator" className="scroll-mt-24 rounded-md border border-hairline bg-panel p-6 lg:p-8">
      <p className="font-mono text-[10px] uppercase tracking-[0.24em] text-cyan">{"// Deterministic Latency Model"}</p>
      <h3 className="mt-2 font-display text-[20px] font-bold text-ink">
        0.84 µs vs. 41.6 s — run the race.
      </h3>
      <div className="mt-6 grid gap-4 lg:grid-cols-2">
        <div className="rounded-md border border-kernel/40 p-5">
          <h4 className="font-mono text-[11px] uppercase tracking-[0.16em] text-kernel">Aryorithm Kernel Path</h4>
          <p className="tabular mt-2 font-mono text-[28px] text-kernel">{aryUs.toFixed(2)} µs</p>
          <div className="relative mt-3 h-2 overflow-hidden rounded bg-hairline">
            <div className="h-full bg-kernel transition-none" style={{ width: `${(aryUs / 0.84) * 100}%` }} />
          </div>
          <ul className="mt-4 space-y-1.5 font-mono text-[11px]">
            {ARY_STAGES.map((s) => (
              <li key={s.label} className={aryUs >= s.us ? "text-kernel" : "text-muted"}>
                {aryUs >= s.us ? "✓" : "·"} {s.label} — {s.us.toFixed(2)}µs
              </li>
            ))}
          </ul>
          {aryComplete && (
            <p className="mt-3 rounded-md border border-kernel/50 bg-kernel/10 px-3 py-2 font-mono text-[11px] text-kernel">
              XDP_DROP executed — frame destroyed before sk_buff allocation.
            </p>
          )}
        </div>
        <div className="rounded-md border border-threat/40 p-5">
          <h4 className="font-mono text-[11px] uppercase tracking-[0.16em] text-threat">Cloud SIEM / EDR Path</h4>
          <p className="tabular mt-2 font-mono text-[28px] text-threat">{cloudTime.toFixed(1)} s</p>
          <div className="relative mt-3 h-2 overflow-hidden rounded bg-hairline">
            <div className="h-full bg-threat transition-none" style={{ width: `${(cloudTime / 41.6) * 100}%` }} />
          </div>
          <ul className="mt-4 space-y-1.5 font-mono text-[11px]">
            {CLOUD_STAGES.map((s) => (
              <li key={s.label} className={cloudTime >= s.at ? "text-threat" : "text-muted"}>
                {cloudTime >= s.at ? "✓" : "·"} {s.label} — {s.at.toFixed(1)}s
              </li>
            ))}
          </ul>
          <p className="mt-3 font-mono text-[10.5px] text-muted">
            EGRESS {(cloudTime * 9.9).toFixed(0)} MB · QUEUE {(cloudTime * 442).toFixed(0)} events
            {cloudTime > 1.2 && <span className="ml-2 text-threat">PLC COMPROMISED</span>}
          </p>
        </div>
      </div>
      <div className="mt-5 flex flex-wrap gap-3">
        <button
          id="simulate-exploit-btn"
          type="button"
          onClick={simulate}
          disabled={running}
          className="rounded-md bg-cyan px-5 py-2.5 font-mono text-[11.5px] font-bold uppercase tracking-[0.1em] text-void hover:brightness-110 disabled:opacity-50"
        >
          {running ? "[ Simulating… ]" : "[ Simulate Exploit ]"}
        </button>
        {(done || cloudTime > 0) && (
          <button
            type="button"
            onClick={reset}
            className="rounded-md border border-hairline px-5 py-2.5 font-mono text-[11.5px] uppercase tracking-[0.1em] text-muted hover:text-ink"
          >
            [ Reset ]
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { CLI_COMMANDS } from "@/data/home";

interface HistLine {
  type: "sys" | "cmd" | "out";
  text: string;
  cls?: string;
}

const CLS: Record<string, string> = {
  ok: "text-kernel",
  warn: "text-telemetry",
  bad: "text-threat",
  dim: "text-muted",
  ink: "text-ink",
  acc: "text-cyan",
};

export default function NexusTerminal() {
  const [history, setHistory] = useState<HistLine[]>([
    { type: "sys", text: "nexus-ctl sandbox — interactive telemetry shell. Pick a preset or type help.", cls: "dim" },
  ]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const bodyRef = useRef<HTMLDivElement | null>(null);
  const timers = useRef<number[]>([]);

  useEffect(() => {
    const el = bodyRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [history]);

  useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), []);

  const run = (raw: string) => {
    const cmd = raw.trim().replace(/^nexus-ctl\s+/, "");
    const full = raw.trim().startsWith("nexus-ctl") ? raw.trim() : `nexus-ctl ${raw.trim()}`;
    if (!cmd) return;
    setHistory((h) => [...h, { type: "cmd", text: `$ ${full}` }]);
    const key = Object.keys(CLI_COMMANDS).find((k) => k === full || k === `nexus-ctl ${cmd}`);
    if (cmd === "help") {
      setHistory((h) => [...h, { type: "out", text: `available: ${Object.keys(CLI_COMMANDS).join(" | ")}`, cls: "dim" }]);
      return;
    }
    if (!key) {
      setHistory((h) => [
        ...h,
        { type: "out", text: `unknown command: ${cmd}`, cls: "bad" },
        { type: "out", text: `available: ${Object.keys(CLI_COMMANDS).join(" | ")}`, cls: "dim" },
      ]);
      return;
    }
    setBusy(true);
    let delay = 0;
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    for (const line of CLI_COMMANDS[key].lines) {
      delay += line.d;
      const snapshot = line;
      timers.current.push(
        window.setTimeout(() => {
          setHistory((h) => [...h, { type: "out", text: snapshot.t, cls: snapshot.c }]);
        }, delay),
      );
    }
    timers.current.push(
      window.setTimeout(() => setBusy(false), delay + 150),
    );
  };

  return (
    <div id="nexus-cli-sandbox" className="scroll-mt-24 overflow-hidden rounded-md border border-hairline bg-panel">
      <div className="flex items-center gap-3 border-b border-hairline bg-void/70 px-4 py-2.5">
        <span className="flex gap-1.5" aria-hidden="true">
          <span className="h-2.5 w-2.5 rounded-full bg-threat/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-telemetry/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-kernel/70" />
        </span>
        <span className="flex-1 font-mono text-[10.5px] text-muted">nexus-ctl — live sandbox</span>
        <span className={`font-mono text-[9.5px] uppercase tracking-[0.12em] ${busy ? "text-telemetry" : "text-kernel"}`}>
          {busy ? "● streaming" : "○ idle"}
        </span>
      </div>
      <div className="grid lg:grid-cols-[220px_1fr]">
        <div className="space-y-2 border-b border-hairline bg-void/50 p-4 lg:border-b-0 lg:border-r">
          {Object.keys(CLI_COMMANDS).map((k) => (
            <button
              key={k}
              type="button"
              disabled={busy}
              onClick={() => run(k)}
              className="block w-full rounded-md border border-hairline px-3 py-2 text-left font-mono text-[10.5px] text-muted transition-colors hover:border-cyan/60 hover:text-cyan disabled:opacity-40"
            >
              <span className="block text-cyan">$ nexus-ctl {CLI_COMMANDS[k].label}</span>
              <span className="mt-0.5 block text-[10px]">{CLI_COMMANDS[k].hint}</span>
            </button>
          ))}
        </div>
        <div>
          <div ref={bodyRef} className="terminal-body h-[320px] overflow-y-auto p-4 font-mono text-[11.5px] leading-relaxed">
            {history.map((h, i) => (
              <p key={i} className={h.type === "cmd" ? "text-cyan" : CLS[h.cls ?? "ink"] ?? "text-ink"}>
                {h.text || " "}
              </p>
            ))}
            {busy && <span className="caret text-cyan">▊</span>}
          </div>
          <form
            className="flex items-center gap-2 border-t border-hairline bg-void/70 px-4 py-2.5"
            onSubmit={(e) => {
              e.preventDefault();
              if (!busy) {
                run(input);
                setInput("");
              }
            }}
          >
            <span className="font-mono text-[12px] text-cyan">$</span>
            <input
              id="cli-input"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              disabled={busy}
              placeholder="nexus-ctl fleet list"
              spellCheck={false}
              className="w-full bg-transparent font-mono text-[12px] text-ink placeholder:text-muted/40 focus:outline-none disabled:opacity-40"
            />
          </form>
        </div>
      </div>
    </div>
  );
}

