      <div className="mt-4 h-2 overflow-hidden rounded bg-hairline">
        <div className={`h-full ${state === "fail" ? "bg-threat" : "bg-kernel"}`} style={{ width: `${(checked / GOLDEN_ATTACKS.length) * 100}%` }} />
